mapper.select:
/*检索项目*/ SELECT FINPROD_ID ID,/*标的类金融产品.金融产品代码 AS 金融产品代码*/ FINPROD_MARKET_ID ||':'|| /*标的类金融产品.市场代码 AS 代码*/ NVL(FINPROD_ABBR, FINPROD_NAME) TEXT/*NVL(标的类金融产品.金融产品简称, 标的类金融产品.金融产品全称) AS 名称*/ FROM /*检索对象*/ FIN_PRODUCT/*标的类金融产品*/ /*检索条件*/
FINPROD_TYPE2 != #{F24} AND FINPROD_MARKET_ID IS NOT NULL /*（标的类金融产品.市场代码 LIKE #%用户输入值%#*/ /*或者 标的类金融产品.金融产品简称 LIKE #%用户输入值%#*/ /*或者 标的类金融产品.金融产品全称 LIKE #%用户输入值%#）*/
and (instr(FINPROD_MARKET_ID, #{search}) > 0 or instr(FINPROD_ABBR, #{search}) > 0 or instr(FINPROD_NAME, #{search}) > 0)
UNION ALL SELECT TARGET_ID ID, TARGET_NAME TEXT FROM OPT_TARGET_INFO
(TARGET_ID like concat(concat('%', #{search,jdbcType=VARCHAR}),'%') OR TARGET_NAME like concat(concat('%', #{search,jdbcType=VARCHAR}),'%'))
/*并且 标的类金融产品.金融产品类型（投管分类） NOT IN (数据字典.金融产品类型(投管用).金融产品分层）*/

/*检索项目*/
SELECT FINPROD_ID ID,/*标的类金融产品.金融产品代码 AS 金融产品代码*/
FINPROD_MARKET_ID ||':'|| /*标的类金融产品.市场代码 AS 代码*/
NVL(FINPROD_ABBR, FINPROD_NAME) TEXT/*NVL(标的类金融产品.金融产品简称, 标的类金融产品.金融产品全称) AS 名称*/
FROM /*检索对象*/
FIN_PRODUCT/*标的类金融产品*/
/*检索条件*/

    FINPROD_TYPE2 = 'F16'
    AND FINPROD_MARKET_ID IS NOT NULL
    /*（标的类金融产品.市场代码 LIKE #%用户输入值%#*/
    /*或者 标的类金融产品.金融产品简称 LIKE #%用户输入值%#*/
    /*或者 标的类金融产品.金融产品全称 LIKE #%用户输入值%#）*/

        and (instr(FINPROD_MARKET_ID, #{search}) > 0 or instr(FINPROD_ABBR, #{search}) > 0 or
        instr(FINPROD_NAME, #{search}) > 0)

/*检索项目*/
SELECT FINPROD_ID ID,/*标的类金融产品.金融产品代码 AS 金融产品代码*/
FINPROD_MARKET_ID ||':'|| /*标的类金融产品.市场代码 AS 代码*/
NVL(FINPROD_ABBR, FINPROD_NAME) TEXT/*NVL(标的类金融产品.金融产品简称, 标的类金融产品.金融产品全称) AS 名称*/
FROM /*检索对象*/
FIN_PRODUCT/*标的类金融产品*/
/*检索条件*/

    FINPROD_TYPE2 in ('F01','F06','F10')
    AND FINPROD_MARKET_ID IS NOT NULL
    /*（标的类金融产品.市场代码 LIKE #%用户输入值%#*/
    /*或者 标的类金融产品.金融产品简称 LIKE #%用户输入值%#*/
    /*或者 标的类金融产品.金融产品全称 LIKE #%用户输入值%#）*/

        and (instr(FINPROD_MARKET_ID, #{search}) > 0 or instr(FINPROD_ABBR, #{search}) > 0 or
        instr(FINPROD_NAME, #{search}) > 0)

/*检索项目*/
SELECT FINPROD_ID ID,/*标的类金融产品.金融产品代码 AS 金融产品代码*/
FINPROD_MARKET_ID ||':'|| /*标的类金融产品.市场代码 AS 代码*/
NVL(FINPROD_ABBR, FINPROD_NAME) TEXT/*NVL(标的类金融产品.金融产品简称, 标的类金融产品.金融产品全称) AS 名称*/
FROM /*检索对象*/
FIN_PRODUCT/*标的类金融产品*/
/*检索条件*/

    FINPROD_TYPE2 not in ('F01','F06','F10')
    and FINPROD_TYPE2 != #{F24}
    and FINPROD_TYPE2 != 'F16'
    AND FINPROD_MARKET_ID IS NOT NULL
    /*（标的类金融产品.市场代码 LIKE #%用户输入值%#*/
    /*或者 标的类金融产品.金融产品简称 LIKE #%用户输入值%#*/
    /*或者 标的类金融产品.金融产品全称 LIKE #%用户输入值%#）*/

        and (instr(FINPROD_MARKET_ID, #{search}) > 0 or instr(FINPROD_ABBR, #{search}) > 0 or
        instr(FINPROD_NAME, #{search}) > 0)
